args.script:
// Check that Three.js loaded, scene built, no errors
const result = {
  threeLoaded: typeof THREE !== 'undefined' || 'module-scoped (expected)',
  canvasExists: !!document.querySelector('canvas'),
  startOverlayVisible: document.getElementById('start').style.display !== 'none',
  hudHidden: document.getElementById('hud').style.display === 'none' || document.getElementById('hud').style.display === '',
};
// canvas size tells us the renderer initialized
const c = document.querySelector('canvas');
if (c) { result.canvasSize = c.width + 'x' + c.height; }
return JSON.stringify(result);

(() => {
  const c = document.querySelector('canvas');
  return JSON.stringify({
    canvasExists: !!c,
    canvasSize: c ? c.width + 'x' + c.height : null,
    startVisible: getComputedStyle(document.getElementById('start')).display,
    webglContext: c ? (c.getContext('webgl2') ? 'webgl2-active' : 'no-webgl') : null,
  });
})()

(() => {
  // hide overlay to reveal the 3D scene, and capture any window errors
  document.getElementById('start').style.display = 'none';
  window.__errors = window.__errors || [];
  window.addEventListener('error', e => window.__errors.push(e.message));
  return 'overlay hidden, error hook installed, prior errors: ' + JSON.stringify(window.__errors);
})()

(() => {
  // let a few frames run, then report errors and scene stats
  return new Promise(resolve => setTimeout(() => {
    resolve(JSON.stringify({
      errors: window.__errors || [],
      // renderer info if accessible via the canvas's context
      bodyChildren: document.body.children.length,
    }));
  }, 1500));
})()

